function priceRow(endpoint: Endpoint): string {
  const perThousand = (endpoint.priceBaseUnits * 1000) / 1_000_000;
  return `| \`${endpoint.path}\` | ${endpoint.priceBaseUnits} | $${perThousand}/1k |`;
