    if (rail === "mpp" && ctx.mpp !== undefined) {
      // Assigned rather than returned, for the same reason as above.
      c.res = await mpp.handle(
        ctx.mpp,
        ctx.screener,
        ctx.metrics,
        endpoint,
        c.req.raw.headers,
        async () => {
          await next();
          return c.res;
        },
      );
      return;
